// Kosaraju's algorithm for strongly connected components.
function kosaraju(graph, n) {
  const visited = new Set();
  const stack = [];
  const dfs1 = (node) => {
    visited.add(node);
    for (const next of graph[node] || []) if (!visited.has(next)) dfs1(next);
    stack.push(node);
  };
  for (let i = 0; i < n; i++) if (!visited.has(i)) dfs1(i);

  const reverse = {};
  for (let i = 0; i < n; i++) reverse[i] = [];
  for (const u in graph) for (const v of graph[u]) reverse[v].push(Number(u));

  visited.clear();
  const sccs = [];
  const dfs2 = (node, comp) => {
    visited.add(node);
    comp.push(node);
    for (const next of reverse[node]) if (!visited.has(next)) dfs2(next, comp);
  };
  while (stack.length) {
    const node = stack.pop();
    if (!visited.has(node)) {
      const comp = [];
      dfs2(node, comp);
      sccs.push(comp);
    }
  }
  return sccs;
}

