import java.util.*;
public class Kosaraju {
    int n;
    List<List<Integer>> adj = new ArrayList<>(), radj = new ArrayList<>();
    boolean[] vis;
    Stack<Integer> stk = new Stack<>();

    void dfs1(int u) {
        vis[u] = true;
        for (int v : adj.get(u)) if (!vis[v]) dfs1(v);
        stk.push(u);
    }
    void dfs2(int u, List<Integer> comp) {
        vis[u] = true; comp.add(u);
        for (int v : radj.get(u)) if (!vis[v]) dfs2(v, comp);
    }
    List<List<Integer>> findSCCs() {
        vis = new boolean[n];
        for (int i = 0; i < n; i++) if (!vis[i]) dfs1(i);
        vis = new boolean[n];
        List<List<Integer>> result = new ArrayList<>();
        while (!stk.isEmpty()) {
            int u = stk.pop();
            if (!vis[u]) {
                List<Integer> comp = new ArrayList<>();
                dfs2(u, comp); result.add(comp);
            }
        }
        return result;
    }
}

