def kosaraju_scc(n, graph):
    visited, order = set(), []
    def dfs1(u):
        visited.add(u)
        for v in graph.get(u, []):
            if v not in visited:
                dfs1(v)
        order.append(u)
    for u in range(n):
        if u not in visited:
            dfs1(u)
    rev = {u: [] for u in range(n)}
    for u in graph:
        for v in graph[u]:
            rev[v].append(u)
    visited.clear()
    sccs = []
    def dfs2(u, comp):
        visited.add(u)
        comp.append(u)
        for v in rev[u]:
            if v not in visited:
                dfs2(v, comp)
    for u in reversed(order):
        if u not in visited:
            comp = []
            dfs2(u, comp)
            sccs.append(comp)
    return sccs

